/// <summary>
/// COC for WMSArrivalOverview form
/// </summary>
[ExtensionOf(formControlStr(WMSArrivalOverview, TOReceiptListButton))]
final class METWHSArrivalOverview_TOReceiptCtrl_Extension
{

}

Method.Source:
/// <summary>
/// This method will pass the selected Purchase orders to 
/// </summary>
public void clicked()
{
    FormControl                     formButtonControl = any2Object(this) as FormControl;
    FormDataSource                  wMSArrivalOverviewTmpDS = formButtonControl.formRun().dataSource(tableStr(WMSArrivalOverviewTmp));
    InventTransferTable             inventTransferTable;
    InventTransRefId                prevInventTransRefId;

    next clicked();

    wMSArrivalOverviewTmpDS.filter(fieldNum(WMSArrivalOverviewTmp, Selected), queryValue(NoYes::Yes));
    wMSArrivalOverviewTmpDS.first();

    WMSArrivalOverviewTmp WMSArrivalOverviewTmp = wMSArrivalOverviewTmpDS.cursor();

    while (wMSArrivalOverviewTmp && WMSArrivalOverviewTmp.InventTransRefId != prevInventTransRefId)
    {
        if (wMSArrivalOverviewTmp.InventTransType != InventTransType::TransferOrderReceive)
        {
            warning("@MET:METTOErrormsg");
        }

        prevInventTransRefId = WMSArrivalOverviewTmp.InventTransRefId;
        inventTransferTable = InventTransferTable::find(WMSArrivalOverviewTmp.InventTransRefId);

        if (InventTransferTable)
        {
            this.sendTOReceiptListReport(InventTransferTable.RecId, InventTransferTable.TransferId);
        }
        wMSArrivalOverviewTmpDS.next();
        WMSArrivalOverviewTmp = wMSArrivalOverviewTmpDS.cursor();
    }
    wMSArrivalOverviewTmpDS.removeFilter();
}

/// <summary>
/// Send TO receipt list report
/// </summary>
/// <param name = "_transferRecId">TO recid</param>
/// <param name = "_transferId">TO number</param>
public void sendTOReceiptListReport(RecId _transferRecId, str _transferId)
{
    METTOReceiptListContract rdpContract = new METTOReceiptListContract();
    rdpContract.parmRecordId(_transferRecId);

    METTOReceiptListController mETTOReceiptListController = new METTOReceiptListController();
    mETTOReceiptListController.parmReportName(ssrsReportStr(METTOReceiptListReport, Report));
    mETTOReceiptListController.parmReportContract().parmRdpContract(rdpContract);
    mETTOReceiptListController.parmShowDialog(false);
    mETTOReceiptListController.parmDialogCaption("@MET:METTransReceiptList");

    SRSPrintDestinationSettings printDestinationSettings = new SRSPrintDestinationSettings();
    printDestinationSettings.parmFileName(_transferId + METConstants::FilePDF);
    printDestinationSettings.fileFormat(SRSReportFileFormat::PDF);
    printDestinationSettings.printMediumType(SRSPrintMediumType::File);

    SrsReportDataContract reportDataContract = new SrsReportDataContract();
    reportDataContract.unpack(mETTOReceiptListController.parmReportContract().pack());
    reportDataContract.parmReportExecutionInfo(new SRSReportExecutionInfo());
    reportDataContract.parmPrintSettings(printDestinationSettings);

    new SrsReportRunService().runReport(reportDataContract);

    Browser br = new Browser();

    System.IO.Stream stream = new System.IO.MemoryStream(reportDataContract.parmReportBytes());

    str downloadurl = File::SendFileToTempStore(stream, printDestinationSettings.parmFileName(), classstr(FileUploadTemporaryStorageStrategy), true);

    new Browser().navigate(downloadurl, true, false);
    info(_transferId);
}
